#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {}
    virtual void speak() const {
        cout << name << "：喵～" << endl;
    }
};

class OrangeCat : public Cat {
public:
    OrangeCat(string n) : Cat(n) {}
    void speak() const {
        cout << name << "：本喵是橘猫，喵喵喵！" << endl;
    }
};

int main() {
    OrangeCat o("{name}");
    Cat& r = o;
    r.speak();
    o.speak();
    return 0;
}
